[{"id":1,"text":"<p><strong>DoorDash Load Balancer</strong></p><p><strong>Description</strong></p><p>You are a Backend Engineer at DoorDash and realized that your service can no longer keep up with traffic. In order to deal with the increased load, your team has decided to scale horizontally by adding more pods that run your service.</p><p>In order to achieve this, your colleague implemented a traffic router that distributes incoming traffic among pods using a round robin algorithm (requests are routed to pods on a cyclical basis). Unfortunately, their implementation doesn’t quite seem to work and you are tasked with debugging the code.</p><p>Their implementation consists of the following classes:</p><ul><li><strong>TrafficRouter</strong>: Represents the Traffic Router. Its constructor takes a list of Backend pods as an argument.</li><li><strong>Pod</strong>: Represents a Pod running your service application. Its constructor takes hostname and port as arguments.</li><li><strong>Backend</strong>: Represents a Pod and its state ("AVAILABLE", "UNAVAILABLE"). Its constructor takes a Pod and a state as arguments.</li><li><strong>HttpRequest</strong>: Represents an incoming Http Request. Its constructor takes an id as an argument. All requests from a user share the same request id.</li></ul><p>And the following methods:</p><ul><li><strong>TrafficRouter.getBackend(request: HttpRequest)</strong>: Returns the next available Pod that can serve the request using a round robin heuristic. If all Pods are unavailable, returns null.</li><li><strong>TrafficRouter.reportAvailability(backend: Backend, state: State)</strong>: Marks a Backend Pod as either available or unavailable.</li><li><strong>TrafficRouter.addBackend(backend: Backend)</strong>: Adds new backends to the rotation at runtime.</li></ul><pre class="ql-syntax" spellcheck="false">import java.io.*;
import java.text.*;
import java.math.*;
import java.util.regex.*;


public class Solution {


&nbsp; &nbsp; public static void main(String[] args) throws IOException {
&nbsp; &nbsp; &nbsp; &nbsp; Solution solution = new Solution();
&nbsp; &nbsp; &nbsp; &nbsp; System.out.println("--- Test 1 ----");
&nbsp; &nbsp; &nbsp; &nbsp; solution.testRoundRobin();
&nbsp; &nbsp; &nbsp; &nbsp; System.out.println("--- Test 2 ----");
&nbsp; &nbsp; &nbsp; &nbsp; solution.testPodUnavailable();
&nbsp; &nbsp; &nbsp; &nbsp; System.out.println("--- Test 3 ----");
&nbsp; &nbsp; &nbsp; &nbsp; solution.testAddBackend();
&nbsp; &nbsp; }


&nbsp; &nbsp; public class HttpRequest {
&nbsp; &nbsp; &nbsp; &nbsp; private final String id;


&nbsp; &nbsp; &nbsp; &nbsp; public HttpRequest(String id) {
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; this.id = id;
&nbsp; &nbsp; &nbsp; &nbsp; }
&nbsp; &nbsp; }


&nbsp; &nbsp; public class Pod {
&nbsp; &nbsp; &nbsp; &nbsp; public final String hostname;
&nbsp; &nbsp; &nbsp; &nbsp; public final int port;


&nbsp; &nbsp; &nbsp; &nbsp; public Pod(String hostname, int port) {
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; this.hostname = hostname;
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; this.port = port;
&nbsp; &nbsp; &nbsp; &nbsp; }
&nbsp; &nbsp; }


&nbsp; &nbsp; class Backend {
&nbsp; &nbsp; &nbsp; &nbsp; public final Pod pod;
&nbsp; &nbsp; &nbsp; &nbsp; private String state;


&nbsp; &nbsp; &nbsp; &nbsp; public Backend(Pod pod, String state) {
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; this.pod = pod;
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; this.state = state;
&nbsp; &nbsp; &nbsp; &nbsp; }


&nbsp; &nbsp; &nbsp; &nbsp; public String getState() {
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; return state;
&nbsp; &nbsp; &nbsp; &nbsp; }


&nbsp; &nbsp; &nbsp; &nbsp; public void setState(String updatedState) {
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; state = updatedState;
&nbsp; &nbsp; &nbsp; &nbsp; }
&nbsp; &nbsp; }


&nbsp; &nbsp; class TrafficRouter {
&nbsp; &nbsp; &nbsp; &nbsp; private List&lt;Backend&gt; backends;


&nbsp; &nbsp; &nbsp; &nbsp; public TrafficRouter(List&lt;Backend&gt; backends) {
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; this.backends = new ArrayList&lt;&gt;(backends);
&nbsp; &nbsp; &nbsp; &nbsp; }


&nbsp; &nbsp; &nbsp; &nbsp; public Backend getBackend(HttpRequest request) {
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; int index = 0;
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Backend backend = backends.get(index);
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; if (backend.getState() == "AVAILABLE") {
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; return backend;
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; }
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; index++;
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; return null;
&nbsp; &nbsp; &nbsp; &nbsp; }


&nbsp; &nbsp; &nbsp; &nbsp; public void reportAvailability(Backend backend, String state) {
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; backend.setState(state);
&nbsp; &nbsp; &nbsp; &nbsp; }


&nbsp; &nbsp; &nbsp; &nbsp; public void addBackend(Backend backend) {
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; this.backends = new ArrayList&lt;Backend&gt;();
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; this.backends.add(backend);
&nbsp; &nbsp; &nbsp; &nbsp; }
&nbsp; &nbsp; }


&nbsp; &nbsp; public void testRoundRobin() {
&nbsp; &nbsp; &nbsp; &nbsp; HttpRequest request = new HttpRequest("e26139c2-dd98-11ed-b5ea-0242ac120002");
&nbsp; &nbsp; &nbsp; &nbsp; Pod pod1 = new Pod("localhost", 8081);
&nbsp; &nbsp; &nbsp; &nbsp; Pod pod2 = new Pod("localhost", 8081);
&nbsp; &nbsp; &nbsp; &nbsp; Backend backend1 = new Backend(pod1, "AVAILABLE");
&nbsp; &nbsp; &nbsp; &nbsp; Backend backend2 = new Backend(pod2, "AVAILABLE");
&nbsp; &nbsp; &nbsp; &nbsp; List&lt;Backend&gt; backends = Arrays.asList(backend1, backend2);
&nbsp; &nbsp; &nbsp; &nbsp; TrafficRouter trafficRouter = new TrafficRouter(backends);


&nbsp; &nbsp; &nbsp; &nbsp; assertEquals(backend1, trafficRouter.getBackend(request));
&nbsp; &nbsp; &nbsp; &nbsp; assertEquals(backend2, trafficRouter.getBackend(request));
&nbsp; &nbsp; &nbsp; &nbsp; assertEquals(backend1, trafficRouter.getBackend(request));
&nbsp; &nbsp; &nbsp; &nbsp; System.out.println("Test Succeeded");
&nbsp; &nbsp; }


&nbsp; &nbsp; public void testPodUnavailable() {
&nbsp; &nbsp; &nbsp; &nbsp; HttpRequest request = new HttpRequest("e26139c2-dd98-11ed-b5ea-0242ac120002");
&nbsp; &nbsp; &nbsp; &nbsp; Pod pod1 = new Pod("localhost", 8081);
&nbsp; &nbsp; &nbsp; &nbsp; Pod pod2 = new Pod("localhost", 8081);
&nbsp; &nbsp; &nbsp; &nbsp; Backend backend1 = new Backend(pod1, "AVAILABLE");
&nbsp; &nbsp; &nbsp; &nbsp; Backend backend2 = new Backend(pod2, "AVAILABLE");
&nbsp; &nbsp; &nbsp; &nbsp; List&lt;Backend&gt; backends = Arrays.asList(backend1, backend2);
&nbsp; &nbsp; &nbsp; &nbsp; TrafficRouter trafficRouter = new TrafficRouter(backends);


&nbsp; &nbsp; &nbsp; &nbsp; assertEquals(backend1, trafficRouter.getBackend(request));
&nbsp; &nbsp; &nbsp; &nbsp; assertEquals(backend2, trafficRouter.getBackend(request));
&nbsp; &nbsp; &nbsp; &nbsp; assertEquals(backend1, trafficRouter.getBackend(request));


&nbsp; &nbsp; &nbsp; &nbsp; trafficRouter.reportAvailability(backend1, "UNAVAILABLE");


&nbsp; &nbsp; &nbsp; &nbsp; assertEquals(null, trafficRouter.getBackend(request));


&nbsp; &nbsp; &nbsp; &nbsp; trafficRouter.reportAvailability(backend2, "AVAILABLE");


&nbsp; &nbsp; &nbsp; &nbsp; assertEquals(backend2, trafficRouter.getBackend(request));
&nbsp; &nbsp; &nbsp; &nbsp; assertEquals(backend2, trafficRouter.getBackend(request));


&nbsp; &nbsp; &nbsp; &nbsp; trafficRouter.reportAvailability(backend1, "AVAILABLE");
&nbsp; &nbsp; &nbsp; &nbsp; assertEquals(backend1, trafficRouter.getBackend(request));
&nbsp; &nbsp; &nbsp; &nbsp; System.out.println("Test Succeeded");
&nbsp; &nbsp; }


&nbsp; &nbsp; public void testAddBackend() {
&nbsp; &nbsp; &nbsp; &nbsp; HttpRequest request = new HttpRequest("e26139c2-dd98-11ed-b5ea-0242ac120002");
&nbsp; &nbsp; &nbsp; &nbsp; Pod pod1 = new Pod("localhost", 8081);
&nbsp; &nbsp; &nbsp; &nbsp; Pod pod2 = new Pod("localhost", 8081);
