[{"id":1,"text":"<p>Intro</p>"},{"id":2,"text":"<p>Player 1 uses 'X' and Player 2 uses 'O'. Player 1 always moves first.</p><p><br></p><p>X _ _</p><p>_ X _</p><p>O O X</p><p>Input: moves = [[1,1],[2,0],[0,0],[2,1],[2,2]]</p><p>Output: 1</p><p><br></p><p>Example 2:</p><p>X X O&nbsp;</p><p>X O _</p><p>O _ _</p><p>Input: moves = [[0,0],[1,1],[0,1],[0,2],[1,0],[2,0]]</p><p>Output: 2</p><p><br></p><p>X O X</p><p>O O X&nbsp;&nbsp;</p><p>X X O</p><p><br></p><pre class="ql-syntax" spellcheck="false">public static int findWinner(int[][] move){
&nbsp; &nbsp; &nbsp; &nbsp; int[] rows = new int[3];
&nbsp; &nbsp; &nbsp; &nbsp; int[] cols = new int[3];


&nbsp; &nbsp; &nbsp; &nbsp; int diag1 = 0;
&nbsp; &nbsp; &nbsp; &nbsp; int diag2 = 0;


&nbsp; &nbsp; &nbsp; &nbsp; for(int i = 0; i&lt; move.length; i++){
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; int m = move[i][0];
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; int n = move[i][1];


&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; int symbol = (i % 2 == 0) ? 1 : -1;&nbsp; // Player1 = +1, Player2 = -1


&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; rows[m] += symbol;
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; cols[n] += symbol;


&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; if(m == n) {
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; diag1 += symbol;
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; }
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; if(m + n == 2){
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; diag2 += symbol;
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; }


&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; // check any winner won?
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; // player1
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; if(rows[m] == 3 || cols[n] == 3 || diag1== 3 || diag2 == 3){
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; return 1;
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; }
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; // payer2
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; if (rows[m] == -3 || cols[n] == -3 || diag1 == -3 || diag2 == -3) {
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; return 2;
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; }
&nbsp; &nbsp; &nbsp; &nbsp; }


&nbsp; &nbsp; &nbsp; &nbsp; return 0;
}
</pre>"},{"id":3,"text":"<p>find overlapping</p><p>Input: intervals = [[1,3],[2,6],[8,10],[15,18]]</p><p>Output: [[1,6],[8,10],[15,18]]</p><p><br></p><p>Input: intervals = [[1,4],[4,5]]</p><p>Output: [[1,5]]</p><p><br></p><p>Input: intervals = [[4,7],[1,4]]</p><p>Output: [[1,7]]</p><pre class="ql-syntax" spellcheck="false">public static List&lt;int[]&gt; findOverlap(int[][] input){
&nbsp; &nbsp; &nbsp; &nbsp; if(input == null || input.length == 0) {
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; return new ArrayList&lt;&gt;();
&nbsp; &nbsp; &nbsp; &nbsp; }
&nbsp; &nbsp; &nbsp; &nbsp; // sort intervals by start
&nbsp; &nbsp; &nbsp; &nbsp; Arrays.sort(input, (v1, v2) -&gt; v1[0]&lt;v2[0] ? -1 : 1);


&nbsp; &nbsp; &nbsp; &nbsp; List&lt;int[]&gt; res = new ArrayList&lt;&gt;();


&nbsp; &nbsp; &nbsp; &nbsp; for(int[] interval : input){
	&nbsp; &nbsp; // If empty → add first, then skip to next loop
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; if(res.size() == 0){
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; res.add(interval);
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; }
	&nbsp; &nbsp;&nbsp;
	&nbsp; &nbsp; // If last end &lt; current start → no overlap
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; if(res.get(res.size()-1)[1] &lt; interval[0])
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; res.add(interval);
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; }else{
		// Overlap → merge by updating end
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; int newEnd = Math.max(res.get(res.size() -1)[1], interval[1]);
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; res.get(res.size() -1)[1]= newEnd;
&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; }
&nbsp; &nbsp; &nbsp; &nbsp; }


&nbsp; &nbsp; &nbsp; &nbsp; return res;
}
</pre>"}]

